package net.fakepixel.housing.database;

import net.fakepixel.housing.house.House;
import org.bukkit.Location;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.MemoryConfiguration;
import org.bukkit.util.io.BukkitObjectInputStream;
import org.bukkit.util.io.BukkitObjectOutputStream;

import java.io.*;
import java.sql.*;
import java.util.*;

public final class JdbcHousingRepository implements HousingRepository {
    private final HousingDatabaseManager database;
    public JdbcHousingRepository(HousingDatabaseManager database){this.database=database;}
    public static String id(House h){return h.getOwner()+"#"+h.getPlotId();}
    @Override public House createHouse(UUID ownerUuid){return new House(ownerUuid,"Unknown","default","house_"+ownerUuid.toString().replace("-",""));}
    @Override public House loadHouse(String houseId) throws Exception {try(Connection c=database.connection();PreparedStatement p=c.prepareStatement("SELECT runtime_data FROM housing_houses WHERE house_id=?")){p.setString(1,houseId);try(ResultSet r=p.executeQuery()){return r.next()?decode(houseId,r.getString(1)):null;}}}
    @Override public List<House> loadHouseByOwner(UUID owner) throws Exception {return query("SELECT house_id,runtime_data FROM housing_houses WHERE owner_uuid=?",owner.toString());}
    @Override public List<House> loadAllHouses() throws Exception {return query("SELECT house_id,runtime_data FROM housing_houses",null);}
    @Override public List<House> loadAllPublicHouses() throws Exception {return query("SELECT house_id,runtime_data FROM housing_houses WHERE visibility='public'",null);}
    private List<House> query(String sql,String value)throws Exception{List<House> out=new ArrayList<>();try(Connection c=database.connection();PreparedStatement p=c.prepareStatement(sql)){if(value!=null)p.setString(1,value);try(ResultSet r=p.executeQuery()){while(r.next())out.add(decode(r.getString(1),r.getString(2)));}}return out;}
    @Override public void saveHouse(House h) throws Exception {try(Connection c=database.connection()){savePlayer(c,h);saveHouse(c,h);saveIndexedMetadata(c,h);}}
    @Override public void saveHouses(Collection<House> houses) throws Exception {try(Connection c=database.connection()){c.setAutoCommit(false);try{for(House h:houses){savePlayer(c,h);saveHouse(c,h);saveIndexedMetadata(c,h);}c.commit();}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}
    private void savePlayer(Connection c,House h)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO housing_players(player_uuid,player_name,updated_at) VALUES(?,?,?) ON DUPLICATE KEY UPDATE player_name=VALUES(player_name),updated_at=VALUES(updated_at)")){p.setString(1,h.getOwner().toString());p.setString(2,h.getOwnerName());p.setLong(3,System.currentTimeMillis());p.executeUpdate();}}
    private void saveIndexedMetadata(Connection c,House h)throws SQLException{Location s=h.getSpawn();String sql="UPDATE housing_houses SET tags_json=?,owner_spawn_world=?,owner_spawn_x=?,owner_spawn_y=?,owner_spawn_z=?,owner_spawn_yaw=?,owner_spawn_pitch=? WHERE house_id=?";try(PreparedStatement p=c.prepareStatement(sql)){p.setString(1,json(h.getTags()));if(s==null){for(int i=2;i<=7;i++)p.setNull(i,i==2?Types.VARCHAR:i>=6?Types.FLOAT:Types.DOUBLE);}else{p.setString(2,s.getWorld()==null?h.getWorldName():s.getWorld().getName());p.setDouble(3,s.getX());p.setDouble(4,s.getY());p.setDouble(5,s.getZ());p.setFloat(6,s.getYaw());p.setFloat(7,s.getPitch());}p.setString(8,id(h));p.executeUpdate();}syncPlayers(c,h,"housing_house_bans",h.getBanned(),null);syncPlayers(c,h,"housing_house_mutes",h.getMuted(),null);syncPlayers(c,h,"housing_house_members",h.getGroups().keySet(),h.getGroups());syncGroups(c,h);}
    private void syncPlayers(Connection c,House h,String table,Collection<UUID> players,Map<UUID,String> groups)throws SQLException{try(PreparedStatement d=c.prepareStatement("DELETE FROM "+table+" WHERE house_id=?")){d.setString(1,id(h));d.executeUpdate();}String sql=groups==null?"INSERT INTO "+table+"(house_id,player_uuid,reason,created_at) VALUES(?,?,'',?)":"INSERT INTO "+table+"(house_id,player_uuid,group_id,added_at) VALUES(?,?,?,?)";try(PreparedStatement p=c.prepareStatement(sql)){for(UUID uuid:players){p.setString(1,id(h));p.setString(2,uuid.toString());if(groups!=null)p.setString(3,groups.get(uuid));p.setLong(groups==null?3:4,System.currentTimeMillis());p.addBatch();}p.executeBatch();}}
    private void syncGroups(Connection c,House h)throws SQLException{try(PreparedStatement d=c.prepareStatement("DELETE FROM housing_house_groups WHERE house_id=?")){d.setString(1,id(h));d.executeUpdate();}try(PreparedStatement p=c.prepareStatement("INSERT INTO housing_house_groups(house_id,group_id,display_name,tag,permissions_json) VALUES(?,?,?,?,?)")){for(String group:h.getCustomGroups()){p.setString(1,id(h));p.setString(2,group);p.setString(3,h.getGroupDisplayName(group));p.setString(4,h.getGroupTag(group));p.setString(5,json(h.getGroupPermissions().get(group)));p.addBatch();}p.executeBatch();}}
    private String json(Collection<String> values){if(values==null||values.isEmpty())return "[]";StringBuilder b=new StringBuilder("[");for(String value:values){if(b.length()>1)b.append(',');b.append('"').append(value==null?"":value.replace("\\","\\\\").replace("\"","\\\"")).append('"');}return b.append(']').toString();}
    @Override public void deleteHouse(String houseId) throws Exception {try(Connection c=database.connection()){c.setAutoCommit(false);try{String[] tables={"housing_parkour_times","housing_parkour","housing_teleport_pads","housing_holograms","housing_npcs","housing_cookies","housing_house_mutes","housing_house_bans","housing_house_groups","housing_house_members"};for(String table:tables){try(PreparedStatement p=c.prepareStatement("DELETE FROM "+table+" WHERE house_id=?")){p.setString(1,houseId);p.executeUpdate();}}try(PreparedStatement p=c.prepareStatement("DELETE FROM housing_houses WHERE house_id=?")){p.setString(1,houseId);p.executeUpdate();}c.commit();}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}
    private void saveHouse(Connection c,House h)throws Exception{String sql="INSERT INTO housing_houses(house_id,owner_uuid,owner_name,plot_id,name,description,visibility,selected_theme,plot_size,cookies,weekly_cookies,template_name,world_name,guest_spawn_world,guest_spawn_x,guest_spawn_y,guest_spawn_z,guest_spawn_yaw,guest_spawn_pitch,runtime_data,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE owner_name=VALUES(owner_name),name=VALUES(name),visibility=VALUES(visibility),selected_theme=VALUES(selected_theme),plot_size=VALUES(plot_size),cookies=VALUES(cookies),weekly_cookies=VALUES(weekly_cookies),guest_spawn_world=VALUES(guest_spawn_world),guest_spawn_x=VALUES(guest_spawn_x),guest_spawn_y=VALUES(guest_spawn_y),guest_spawn_z=VALUES(guest_spawn_z),guest_spawn_yaw=VALUES(guest_spawn_yaw),guest_spawn_pitch=VALUES(guest_spawn_pitch),runtime_data=VALUES(runtime_data),updated_at=VALUES(updated_at)";try(PreparedStatement p=c.prepareStatement(sql)){Location g=h.getGuestSpawn();int i=1;p.setString(i++,id(h));p.setString(i++,h.getOwner().toString());p.setString(i++,h.getOwnerName());p.setInt(i++,h.getPlotId());p.setString(i++,h.getName());p.setString(i++,"");p.setString(i++,h.isPublicHouse()?"public":h.getVisitingRule());p.setString(i++,h.getTheme());p.setInt(i++,h.getPlotSize());p.setInt(i++,h.getCookies());p.setInt(i++,h.getWeeklyCookies());p.setString(i++,h.getTemplate());p.setString(i++,h.getWorldName());if(g==null){for(int n=0;n<6;n++)p.setNull(i++,n==0?Types.VARCHAR:n>=4?Types.FLOAT:Types.DOUBLE);}else{p.setString(i++,g.getWorld()==null?h.getWorldName():g.getWorld().getName());p.setDouble(i++,g.getX());p.setDouble(i++,g.getY());p.setDouble(i++,g.getZ());p.setFloat(i++,g.getYaw());p.setFloat(i++,g.getPitch());}p.setString(i++,encode(h));p.setLong(i++,h.getCreatedAt());p.setLong(i,System.currentTimeMillis());p.executeUpdate();}}
    private String encode(House h)throws Exception{MemoryConfiguration root=new MemoryConfiguration();ConfigurationSection section=root.createSection("house");h.save(section);Map<String,Object> leaves=new LinkedHashMap<>();for(Map.Entry<String,Object> e:section.getValues(true).entrySet())if(!(e.getValue() instanceof ConfigurationSection))leaves.put(e.getKey(),e.getValue());ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(BukkitObjectOutputStream out=new BukkitObjectOutputStream(bytes)){out.writeObject(leaves);}return Base64.getEncoder().encodeToString(bytes.toByteArray());}
    @SuppressWarnings("unchecked") private House decode(String id,String payload)throws Exception{Map<String,Object> values;try(BukkitObjectInputStream in=new BukkitObjectInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(payload)))){values=(Map<String,Object>)in.readObject();}MemoryConfiguration root=new MemoryConfiguration();ConfigurationSection section=root.createSection("house");for(Map.Entry<String,Object> e:values.entrySet())section.set(e.getKey(),e.getValue());return House.fromConfig(id.substring(0,id.indexOf('#')),section);}
    @Override public void saveGuestSpawn(String id,Location l)throws Exception{update("UPDATE housing_houses SET guest_spawn_world=?,guest_spawn_x=?,guest_spawn_y=?,guest_spawn_z=?,guest_spawn_yaw=?,guest_spawn_pitch=?,updated_at=? WHERE house_id=?",l.getWorld()==null?null:l.getWorld().getName(),l.getX(),l.getY(),l.getZ(),l.getYaw(),l.getPitch(),System.currentTimeMillis(),id);}
    @Override public void saveTheme(String id,String theme)throws Exception{update("UPDATE housing_houses SET selected_theme=?,updated_at=? WHERE house_id=?",theme,System.currentTimeMillis(),id);}
    @Override public void savePlotSize(String id,int size)throws Exception{update("UPDATE housing_houses SET plot_size=?,updated_at=? WHERE house_id=?",size,System.currentTimeMillis(),id);}
    @Override public void saveGroup(String house,String group,String name,String tag,String permissions)throws Exception{update("INSERT INTO housing_house_groups(house_id,group_id,display_name,tag,permissions_json) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE display_name=VALUES(display_name),tag=VALUES(tag),permissions_json=VALUES(permissions_json)",house,group,name,tag,permissions);}
    @Override public void saveNpc(String npc,String house,String json)throws Exception{update("INSERT INTO housing_npcs(npc_id,house_id,name,skin,world,x,y,z,yaw,pitch,action_type,action_data_json,created_at,updated_at) VALUES(?,?,?,'','',0,0,0,0,0,'json',?,?,?) ON DUPLICATE KEY UPDATE action_data_json=VALUES(action_data_json),updated_at=VALUES(updated_at)",npc,house,npc,json,System.currentTimeMillis(),System.currentTimeMillis());}
    @Override public List<String> loadNpcData()throws Exception{List<String> out=new ArrayList<>();try(Connection c=database.connection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT action_data_json FROM housing_npcs WHERE house_id IS NULL")){while(r.next())out.add(r.getString(1));}return out;}
    @Override public void saveHologram(String hologram,String house,String json)throws Exception{update("INSERT INTO housing_holograms(hologram_id,house_id,world,x,y,z,lines_json,created_at,updated_at) VALUES(?,?,'',0,0,0,?,?,?) ON DUPLICATE KEY UPDATE lines_json=VALUES(lines_json),updated_at=VALUES(updated_at)",hologram,house,json,System.currentTimeMillis(),System.currentTimeMillis());}
    @Override public void saveTeleportPad(String pad,String house,String json)throws Exception{update("INSERT INTO housing_teleport_pads(pad_id,house_id,name,world,x,y,z,particles_enabled,sound_enabled,created_at,updated_at) VALUES(?,?,?,'',0,0,0,1,1,?,?) ON DUPLICATE KEY UPDATE name=VALUES(name),updated_at=VALUES(updated_at)",pad,house,json,System.currentTimeMillis(),System.currentTimeMillis());}
    @Override public void saveParkourData(String house,String json)throws Exception{update("INSERT INTO housing_parkour(house_id,checkpoints_json,updated_at) VALUES(?,?,?) ON DUPLICATE KEY UPDATE checkpoints_json=VALUES(checkpoints_json),updated_at=VALUES(updated_at)",house,json,System.currentTimeMillis());}
    @Override public void saveParkourTime(String house,UUID player,long time)throws Exception{update("INSERT INTO housing_parkour_times(house_id,player_uuid,best_time_millis,completed_at) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE best_time_millis=LEAST(best_time_millis,VALUES(best_time_millis)),completed_at=VALUES(completed_at)",house,player.toString(),time,System.currentTimeMillis());}
    @Override public List<String> loadBrowseData()throws Exception{List<String> out=new ArrayList<>();try(Connection c=database.connection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT browse_data FROM housing_player_browse")){while(r.next())out.add(r.getString(1));}return out;}
    @Override public void saveBrowseData(UUID player,String data)throws Exception{update("INSERT INTO housing_player_browse(player_uuid,browse_data,updated_at) VALUES(?,?,?) ON DUPLICATE KEY UPDATE browse_data=VALUES(browse_data),updated_at=VALUES(updated_at)",player.toString(),data,System.currentTimeMillis());}
    @Override public boolean hasUnlock(UUID player,String type,String id)throws Exception{try(Connection c=database.connection();PreparedStatement p=c.prepareStatement("SELECT 1 FROM housing_unlocks WHERE player_uuid=? AND unlock_type=? AND unlock_id=?")){p.setString(1,player.toString());p.setString(2,type);p.setString(3,id);try(ResultSet r=p.executeQuery()){return r.next();}}}
    @Override public void saveUnlock(UUID player,String type,String id)throws Exception{update("INSERT IGNORE INTO housing_unlocks(player_uuid,unlock_type,unlock_id,unlocked_at) VALUES(?,?,?,?)",player.toString(),type,id,System.currentTimeMillis());}
    @Override public Map<UUID,UUID> loadInvites()throws Exception{Map<UUID,UUID> out=new HashMap<>();long now=System.currentTimeMillis();try(Connection c=database.connection()){try(PreparedStatement d=c.prepareStatement("DELETE FROM housing_house_invites WHERE expires_at<=?")){d.setLong(1,now);d.executeUpdate();}try(PreparedStatement p=c.prepareStatement("SELECT player_uuid,owner_uuid FROM housing_house_invites WHERE expires_at>?")){p.setLong(1,now);try(ResultSet r=p.executeQuery()){while(r.next())out.put(UUID.fromString(r.getString(1)),UUID.fromString(r.getString(2)));}}}return out;}
    @Override public void saveInvite(UUID player,UUID owner,String houseId,long expiresAt)throws Exception{update("INSERT INTO housing_house_invites(player_uuid,owner_uuid,house_id,created_at,expires_at) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE owner_uuid=VALUES(owner_uuid),house_id=VALUES(house_id),created_at=VALUES(created_at),expires_at=VALUES(expires_at)",player.toString(),owner.toString(),houseId,System.currentTimeMillis(),expiresAt);}
    private void update(String sql,Object... values)throws Exception{try(Connection c=database.connection();PreparedStatement p=c.prepareStatement(sql)){for(int i=0;i<values.length;i++)p.setObject(i+1,values[i]);p.executeUpdate();}}
}
